z,al=symbols('z alpha'); a={(0,0):1}; A=lambda n,m: a.get((n,m),0)
for n in range(1,5):
  for m in range(0,n+1):
    if 3*n>4*m: a[(n,m)]=A(n-1,m)*(3*n-2-4*m)*(3*n-1-4*m)/(16*pi*I)-pi*I*A(n-1,m-1)
v=sum(c*z**(-3*n-1+4*m)*al**(-n) for (n,m),c in a.items())
R=expand(diff(v,z,2)/(16*pi*I)-pi*I*z**2*v-al*z*v)
